//		OnConflict(sql.ConflictColumns(columns...)).
//		Exec(ctx)
func (_c *RuntimeOrphanCreateBulk) OnConflictColumns(columns ...string) *RuntimeOrphanUpsertBulk {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &RuntimeOrphanUpsertBulk{
		create: _c,
	}
}

// RuntimeOrphanUpsertBulk is the builder for "upsert"-ing
// a bulk of RuntimeOrphan nodes.
type RuntimeOrphanUpsertBulk struct {
	create *RuntimeOrphanCreateBulk
}

// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.RuntimeOrphan.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(runtimeorphan.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *RuntimeOrphanUpsertBulk) UpdateNewValues() *RuntimeOrphanUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(runtimeorphan.FieldID)
			}
			if _, exists := b.mutation.Kind(); exists {
				s.SetIgnore(runtimeorphan.FieldKind)
			}
			if _, exists := b.mutation.BrokerID(); exists {
				s.SetIgnore(runtimeorphan.FieldBrokerID)
			}
			if _, exists := b.mutation.RuntimeTarget(); exists {
				s.SetIgnore(runtimeorphan.FieldRuntimeTarget)
			}
			if _, exists := b.mutation.ProjectID(); exists {
				s.SetIgnore(runtimeorphan.FieldProjectID)
			}
			if _, exists := b.mutation.Slug(); exists {
				s.SetIgnore(runtimeorphan.FieldSlug)
			}
			if _, exists := b.mutation.AgentID(); exists {
				s.SetIgnore(runtimeorphan.FieldAgentID)
			}
			if _, exists := b.mutation.FirstSeenAt(); exists {
				s.SetIgnore(runtimeorphan.FieldFirstSeenAt)
			}
		}
	}))
	return u
}

